<?php
declare(strict_types=1);namespace App\Controllers;use App\Policies\AuthPolicy;use App\Services\AccountabilityService;use App\Services\ExportService;use App\Support\Database;use App\Support\Security;use App\Support\View;
final class AccountabilityController {public function dashboard(array $p):string{$tid=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('export',$tid);return View::render('admin/accountability',['title'=>'Prestacao de contas','tournament_id'=>$tid,'user'=>$u,'metrics'=>(new AccountabilityService(Database::connection()))->dashboard($tid)]);}public function export(array $p):never{$tid=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('export',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{$e=new ExportService(Database::connection());$job=$e->create($tid,(int)$u['id'],(string)$_POST['type']);$e->run($job);header('Location: /admin/tournaments/'.$tid.'/accountability');exit;}catch(\Throwable $e){http_response_code(422);exit($e->getMessage());}}}
